<script setup lang="ts">
import {computed,ref,watch,onMounted,onUnmounted,nextTick} from 'vue'
import {Search} from 'lucide-vue-next'
import type {Chapter} from '../domain/local-contract'
const props=defineProps<{chapters:Chapter[];active:number}>(),emit=defineEmits<{select:[number]}>(),query=ref(''),number=ref(props.active+1),windowRef=ref<HTMLElement|null>(null),top=ref(0),windowHeight=ref(400),focused=ref(props.active)
const rowHeight=52,items=computed(()=>{const q=query.value.trim().normalize('NFKC').toLocaleLowerCase('zh');return props.chapters.map((chapter,index)=>({chapter,index})).filter(r=>!q||r.chapter.title.normalize('NFKC').toLocaleLowerCase('zh').includes(q)||String(r.index+1)===q)}),start=computed(()=>Math.max(0,Math.floor(top.value/rowHeight)-4)),visible=computed(()=>items.value.slice(start.value,start.value+Math.ceil(windowHeight.value/rowHeight)+8))
let resize:ResizeObserver|undefined,disposed=false
function scroll(){top.value=windowRef.value?.scrollTop||0}
function locate(index:number){const position=items.value.findIndex(r=>r.index===index);if(position<0||!windowRef.value)return;windowRef.value.scrollTop=Math.max(0,position*rowHeight-windowHeight.value/2+rowHeight/2);scroll()}
function go(){if(Number.isInteger(number.value)&&number.value>=1&&number.value<=props.chapters.length)emit('select',number.value-1)}
async function key(event:KeyboardEvent){if((event.target as Element)?.closest('input'))return;const position=items.value.findIndex(r=>r.index===focused.value),delta=event.key==='ArrowDown'?1:event.key==='ArrowUp'?-1:0,next=event.key==='Home'?0:event.key==='End'?items.value.length-1:position+delta;if(!delta&&!['Home','End'].includes(event.key)||!items.value[next])return;event.preventDefault();focused.value=items.value[next]!.index;locate(focused.value);await nextTick();if(!disposed)windowRef.value?.querySelector<HTMLElement>('[data-chapter-index="'+focused.value+'"]')?.focus()}
watch(query,()=>{if(windowRef.value)windowRef.value.scrollTop=0;top.value=0;focused.value=items.value[0]?.index||0})
watch(()=>props.active,index=>{number.value=index+1;focused.value=index;locate(index)})
onMounted(()=>{resize=new ResizeObserver(()=>{windowHeight.value=windowRef.value?.clientHeight||400});if(windowRef.value){resize.observe(windowRef.value);windowHeight.value=windowRef.value.clientHeight;locate(props.active)}})
onUnmounted(()=>{disposed=true;resize?.disconnect()})
</script>
<template><div class="chapter-directory"><div class="directory-search"><Search :size="17" aria-hidden="true"/><input v-model="query" type="search" aria-label="搜索目录" placeholder="章节名或序号" maxlength="500"></div><form class="directory-jump" @submit.prevent="go"><label>跳到<input v-model.number="number" type="number" :min="1" :max="chapters.length" aria-label="章节序号" required></label><span>/ {{chapters.length}}</span><button :disabled="!chapters.length" type="submit">打开</button></form><div ref="windowRef" class="directory-window" :style="{height:Math.min(520,Math.max(52,items.length*52))+'px'}" role="navigation" aria-label="章节" @scroll.passive="scroll" @keydown="key"><div class="directory-space" :style="{height:items.length*52+'px'}"><button v-for="row in visible" :key="row.chapter.id" :data-chapter-index="row.index" :style="{top:items.indexOf(row)*52+'px'}" :aria-current="row.index===active?'page':undefined" :title="row.chapter.title" @focus="focused=row.index" @click="emit('select',row.index)"><small aria-hidden="true">{{String(row.index+1).padStart(2,'0')}}</small><span>{{row.chapter.title}}</span></button></div></div><p v-if="!items.length" role="status" class="final-subtle">没有找到章节</p></div></template>
<style scoped>
.chapter-directory{display:grid;gap:18px}.directory-search{display:flex;align-items:center;gap:10px;border:1px solid var(--edge);border-radius:12px;padding:0 14px}.directory-search input{border:0;background:transparent;color:var(--ink);width:100%;min-height:44px;font:inherit}.directory-jump{display:flex;align-items:center;gap:14px;color:var(--quiet);font-size:13px}.directory-jump label{display:flex;align-items:center;gap:10px}.directory-jump input{width:94px;min-height:44px;border:1px solid var(--edge);border-radius:10px;padding:10px;background:var(--canvas);color:var(--ink)}.directory-jump button{margin-left:auto;min-height:44px}.directory-window{overflow:auto;max-height:52dvh;overscroll-behavior:contain;position:relative}.directory-space{position:relative}.directory-space button{position:absolute;left:0;right:0;width:100%;height:52px;min-height:44px;border:0;border-radius:10px;background:transparent;display:flex;align-items:center;text-align:left;gap:16px;padding:8px 14px}.directory-space small{color:var(--quiet);font-size:12px;min-width:36px;font-variant-numeric:tabular-nums}.directory-space span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.directory-space button[aria-current=page]{background:var(--wash);color:var(--accent)}
</style>
